// Cloudflare entrypoint: HTTP goes to the OpenNext handler, and the four-hour
// cron calls back into the app to run Ada's research pass.
// @ts-ignore generated by the OpenNext Cloudflare build
import { default as openNextWorker } from "./.open-next/worker.js";

type TenantEnv = {
  CRON_SECRET?: string;
  DEEPSEEK_API_KEY?: string;
};

type WorkerContext = { waitUntil: (promise: Promise<unknown>) => void };
type ScheduledEvent = { scheduledTime: number; cron?: string };

type OpenNextHandler = {
  fetch: (request: Request, env: TenantEnv, context: WorkerContext) => Promise<Response>;
};

const handler = openNextWorker as unknown as OpenNextHandler;

const invokeApp = (path: string, body: unknown, env: TenantEnv, context: WorkerContext) =>
  handler.fetch(
    new Request(`https://alaguillotine-internal.invalid${path}`, {
      method: "POST",
      headers: {
        authorization: `Bearer ${env.CRON_SECRET ?? ""}`,
        "content-type": "application/json",
      },
      body: JSON.stringify(body),
    }),
    env,
    context,
  );

export default {
  fetch: (request: Request, env: TenantEnv, context: WorkerContext) =>
    handler.fetch(request, env, context),

  scheduled(event: ScheduledEvent, env: TenantEnv, context: WorkerContext) {
    if (!env.CRON_SECRET) {
      console.error("clock_cron_misconfigured");
      return;
    }
    // The feed gets its own five-minute slot, separate from the blade. A news
    // cycle is shorter than fifteen minutes; the pass is bounded and parallel,
    // so it fits inside the window rather than overrunning the next one.
    if (event.cron === "*/5 * * * *") {
      context.waitUntil(
        invokeApp(
          "/api/feed/refresh",
          { scheduledTime: event.scheduledTime },
          env,
          context,
        ).then((response) => {
          if (!response.ok) {
            throw new Error(`/api/feed/refresh returned HTTP ${response.status}.`);
          }
        }),
      );
      // A dispatch that outlived one request is resumed here. The route skips
      // the call entirely when the last dispatch is recent, so this costs
      // nothing on a normal day.
      context.waitUntil(
        invokeApp(
          "/api/posts/refresh",
          { scheduledTime: event.scheduledTime },
          env,
          context,
        ).then((response) => {
          if (!response.ok) {
            throw new Error(`/api/posts/refresh returned HTTP ${response.status}.`);
          }
        }),
      );
      return;
    }
    // The findings pass keeps its own quarter-hour offset. One archive search
    // per run: the grid is every outlet crossed with every finding word, and
    // the cursor walks it. No roster decides who can appear.
    if (event.cron === "7,22,37,52 * * * *") {
      context.waitUntil(
        invokeApp(
          "/api/findings/line",
          { scheduledTime: event.scheduledTime },
          env,
          context,
        ).then((response) => {
          if (!response.ok) {
            throw new Error(`/api/findings/line returned HTTP ${response.status}.`);
          }
        }),
      );
      return;
    }
    // The blade keeps its own time: sentence at the reading, drop at the
    // hour. No model call, so a slot no longer depends on a visitor.
    if (event.cron === "*/15 * * * *") {
      context.waitUntil(
        invokeApp(
          "/api/hateometer/tick",
          { scheduledTime: event.scheduledTime },
          env,
          context,
        ).then((response) => {
          if (!response.ok) {
            throw new Error(`/api/hateometer/tick returned HTTP ${response.status}.`);
          }
        }),
      );
      return;
    }
    // One scrape, four hours apart. The page fakes the liveness, not the bill.
    //
    // The DeepSeek key is search-only, and the backfill is the largest
    // consumer: eight cases at six queries each, twice a day. It now runs
    // once a day at 00:30 UTC with five cases. The clock, coverage and
    // numbers passes still run every twelve hours.
    // Congress keeps its own record. Once a day, read the newest roll calls
    // and file the members whose votes the reporting names. No model call on
    // the votes themselves: the clerk's XML is the source.
    if (event.cron === "0 7 * * *") {
      context.waitUntil(
        invokeApp(
          "/api/congress/refresh",
          { scheduledTime: event.scheduledTime },
          env,
          context,
        ).then((response) => {
          if (!response.ok) {
            throw new Error(`/api/congress/refresh returned HTTP ${response.status}.`);
          }
        }),
      );
      return;
    }

    // State and local subsidy registers, monthly: fifty websites, one shape.
    // Nothing here calls a model, so it runs on the first of the month at 05:00
    // and leaves the rest of the schedule alone.
    if (event.cron === "0 5 1 * *") {
      context.waitUntil(
        invokeApp(
          "/api/subsidies/ingest",
          { scheduledTime: event.scheduledTime },
          env,
          context,
        ).then((response) => {
          if (!response.ok) {
            throw new Error(`/api/subsidies/ingest returned HTTP ${response.status}.`);
          }
        }),
      );
      return;
    }

    // The register read: no search, no model, so it gets its own quiet slot.
    // Without this branch the expression is deployed and does nothing but the
    // clock refresh, which is the failure mode where a schedule looks alive.
    if (event.cron === "15 6 * * *") {
      context.waitUntil(
        invokeApp(
          "/api/sanctions/ingest",
          { scheduledTime: event.scheduledTime },
          env,
          context,
        ).then((response) => {
          if (!response.ok) {
            throw new Error(`/api/sanctions/ingest returned HTTP ${response.status}.`);
          }
        }),
      );
      return;
    }

    const twelveHour = event.cron === "30 */12 * * *";
    const midnight = new Date(event.scheduledTime).getUTCHours() === 0;
    const paths = twelveHour
      ? [
          "/api/clock/refresh",
          "/api/hateometer/refresh",
          "/api/posts/refresh",
          "/api/manifesto/refresh",
          "/api/coverage?batch=2",
          "/api/numbers?batch=2",
          "/api/claims/verify?limit=20",
          "/api/claims/date?limit=200",
          "/api/claims/takes?limit=60",
          "/api/claim-feed/publish?days=3",
          ...(midnight
            ? [
                "/api/backfill?batch=2",
                "/api/backfill/person?batch=1",
                "/api/backfill/person?recent=1&batch=2",
              ]
            : []),
        ]
      : ["/api/clock/refresh"];

    for (const path of paths) {
      context.waitUntil(
        invokeApp(path, { scheduledTime: event.scheduledTime }, env, context).then((response) => {
          if (!response.ok) {
            throw new Error(`${path} returned HTTP ${response.status}.`);
          }
        }),
      );
    }
  },
};

// The OpenNext adapter may depend on these named handlers for its internal cache.
// @ts-ignore generated by the OpenNext Cloudflare build
export { DOQueueHandler, DOShardedTagCache } from "./.open-next/worker.js";
